import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA code that fuses the two AvgPool3d(kernel=2) operations into one AvgPool3d(kernel=4) operation
fused_avg_pool_3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_avg_pool_3d_kernel(const float* input, float* output,
                                         int B, int C, int D, int H, int W,
                                         int DOut, int HOut, int WOut) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * C * DOut * HOut * WOut;
    if (idx >= total) return;

    int ow = idx % WOut;
    int oh = (idx / WOut) % HOut;
    int od = (idx / (WOut * HOut)) % DOut;
    int c  = (idx / (WOut * HOut * DOut)) % C;
    int b  = (idx / (WOut * HOut * DOut * C));

    // Each output element is the average of a 4x4x4 region in the input
    int d_start = od * 4;
    int h_start = oh * 4;
    int w_start = ow * 4;

    float sum_val = 0.0f;
    for (int kd = 0; kd < 4; kd++) {
        for (int kh = 0; kh < 4; kh++) {
            for (int kw = 0; kw < 4; kw++) {
                int in_d = d_start + kd;
                int in_h = h_start + kh;
                int in_w = w_start + kw;
                int in_idx = ((b * C + c) * D + in_d) * H * W + in_h * W + in_w;
                sum_val += input[in_idx];
            }
        }
    }
    output[idx] = sum_val / 64.0f; // 4*4*4 = 64
}

torch::Tensor fused_avg_pool_3d_cuda(torch::Tensor x) {
    auto B = x.size(0);
    auto C = x.size(1);
    auto D = x.size(2);
    auto H = x.size(3);
    auto W = x.size(4);

    // We assume dimensions are multiples of 4
    int DOut = D / 4;
    int HOut = H / 4;
    int WOut = W / 4;

    auto options = torch::TensorOptions().dtype(x.dtype()).device(x.device());
    auto out = torch::zeros({B, C, DOut, HOut, WOut}, options);

    int total = B * C * DOut * HOut * WOut;
    const int block_size = 256;
    const int grid_size = (total + block_size - 1) / block_size;

    fused_avg_pool_3d_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, D, H, W, DOut, HOut, WOut
    );
    return out;
}
"""

fused_avg_pool_3d_cpp_source = r"""
torch::Tensor fused_avg_pool_3d_cuda(torch::Tensor x);
"""

# Build the fused average pooling extension
fused_avg_pool_3d = load_inline(
    name="fused_avg_pool_3d",
    cpp_sources=fused_avg_pool_3d_cpp_source,
    cuda_sources=fused_avg_pool_3d_source,
    functions=["fused_avg_pool_3d_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses two AvgPool3d(kernel=2) operations into one custom CUDA kernel
    for AvgPool3d(kernel=4).
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size, stride=stride, padding=padding
        )
        self.batch_norm = nn.BatchNorm3d(out_channels)

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.batch_norm(x)
        # Replace the two AvgPool3d(kernel=2) calls with a single fused CUDA kernel (kernel=4).
        x = fused_avg_pool_3d.fused_avg_pool_3d_cuda(x)
        return x

def get_inputs():
    batch_size = 128
    in_channels = 3
    depth, height, width = 32, 32, 32
    return [torch.randn(batch_size, in_channels, depth, height, width).cuda()]

def get_init_inputs():
    in_channels = 3
    out_channels = 16
    kernel_size = 3
    stride = 2
    padding = 1
    bias_shape = (out_channels, 1, 1, 1)
    return [in_channels, out_channels, kernel_size, stride, padding, bias_shape]
